$ErrorActionPreference='Stop';$principal=[Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent();if(-not$principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Administrator token required.'};Set-Location (Resolve-Path (Join-Path $PSScriptRoot '..\..'))
$cfg=@{};Get-Content .env|?{$_-match'^[^#].*='}|%{$p=$_.Split('=',2);$cfg[$p[0]]=$p[1]};$d=[DateTimeOffset]::UtcNow.AddSeconds(90);do{try{$login=Invoke-RestMethod -Method Post http://localhost:8080/api/v1/auth/token -ContentType application/json -Body (@{username=$cfg.PLATFORM_BOOTSTRAP_USER;password=$cfg.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json)}catch{$login=$null};if(-not$login){Start-Sleep 1}}while((-not$login)-and[DateTimeOffset]::UtcNow-lt$d);if(-not$login){throw 'Gateway login readiness timed out'};$headers=@{Authorization="Bearer $($login.access_token)"};$before=@((Invoke-RestMethod 'http://localhost:8080/api/v1/endpoints?pageSize=500' -Headers $headers).data.items.id)
