function Sql($q){$v=docker exec deployment-postgres-1 psql -v ON_ERROR_STOP=1 -U platform -d platform -Atc $q;if($LASTEXITCODE-ne0){throw 'SQL failed'};$v};function Add($name,$status,$evidence){$rows.Add([ordered]@{criterion=$name;status=$status;evidence=$evidence})}
function Ready([int]$seconds=120){$d=[DateTimeOffset]::UtcNow.AddSeconds($seconds);do{Start-Sleep 1;try{$ok=(Invoke-WebRequest http://localhost:8080/health/ready -UseBasicParsing -TimeoutSec 2).StatusCode-eq200}catch{$ok=$false}}while((-not$ok)-and[DateTimeOffset]::UtcNow-lt$d);$ok}
function Events([DateTimeOffset]$start,[int[]]$ports,[int]$minimum=1){$from=[uri]::EscapeDataString($start.AddSeconds(-2).ToString('O'));$to=[uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddMinutes(1).ToString('O'));$d=[DateTimeOffset]::UtcNow.AddSeconds(90);do{Start-Sleep 1;$byId=@{};foreach($port in $ports){foreach($field in @('localPort','remotePort')){@((Invoke-RestMethod "http://localhost:8080/api/v1/network-events?endpointId=$endpoint&$field=$port&from=$from&to=$to&pageSize=500" -Headers $headers).data.items)|%{$byId[$_.eventId]=$_}}};$matched=@($byId.Values);$stable=if($matched.Count-eq$script:lastCount){$script:stable+1}else{0};$script:lastCount=$matched.Count;$script:stable=$stable}while(($matched.Count-lt$minimum-or$stable-lt2)-and[DateTimeOffset]::UtcNow-lt$d);$matched}
function TcpSuccess([int]$count,[bool]$burst,[bool]$v6){$ip=if($v6){[Net.IPAddress]::IPv6Loopback}else{[Net.IPAddress]::Loopback};$family=if($v6){[Net.Sockets.AddressFamily]::InterNetworkV6}else{[Net.Sockets.AddressFamily]::InterNetwork};$listener=[Net.Sockets.TcpListener]::new($ip,0);$listener.Start(256);$port=([Net.IPEndPoint]$listener.LocalEndpoint).Port;$clients=[Collections.Generic.List[Net.Sockets.TcpClient]]::new();if($burst){$tasks=[Collections.Generic.List[Threading.Tasks.Task]]::new();1..$count|%{$c=[Net.Sockets.TcpClient]::new($family);$clients.Add($c);$tasks.Add($c.ConnectAsync($ip,$port))};$null=[Threading.Tasks.Task]::WhenAll($tasks.ToArray()).GetAwaiter().GetResult();1..$count|%{$s=$listener.AcceptTcpClient();$s.Dispose()}}else{1..$count|%{$a=$listener.AcceptTcpClientAsync();$c=[Net.Sockets.TcpClient]::new($family);$c.Connect($ip,$port);$clients.Add($c);$s=$a.GetAwaiter().GetResult();$s.Dispose();$c.Dispose()}};$clients|%{$_.Dispose()};$listener.Stop();,$port}
function TcpFail([int]$count){$l=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,0);$l.Start();$port=([Net.IPEndPoint]$l.LocalEndpoint).Port;$l.Stop();1..$count|%{$c=$null;try{$c=[Net.Sockets.TcpClient]::new();$c.Connect([Net.IPAddress]::Loopback,$port)}catch [Net.Sockets.SocketException]{}finally{if($c){$c.Dispose()}}};,$port}
function Udp([int]$count){$receiver=[Net.Sockets.UdpClient]::new([Net.IPEndPoint]::new([Net.IPAddress]::Loopback,0));$port=([Net.IPEndPoint]$receiver.Client.LocalEndPoint).Port;$sender=[Net.Sockets.UdpClient]::new();1..$count|%{$sender.Send([byte[]](1,2,3),3,[Net.IPEndPoint]::new([Net.IPAddress]::Loopback,$port))|Out-Null};1..$count|%{$remote=[Net.IPEndPoint]::new([Net.IPAddress]::Any,0);$null=$receiver.Receive([ref]$remote)};$sender.Dispose();$receiver.Dispose();,$port}
function Profile($letter,$mode,[int]$logical,[scriptblock]$work,[scriptblock]$assert){$script:lastCount=-1;$script:stable=0;$start=[DateTimeOffset]::UtcNow;$cpu0=$agent.TotalProcessorTime.TotalMilliseconds;$watch=[Diagnostics.Stopwatch]::StartNew();$ports=@(&$work);$watch.Stop();$ev=@(Events $start $ports 1);$health=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/network-telemetry-health" -Headers $headers).data;$kinds=@{};$ev|Group-Object kind|%{$kinds[$_.Name]=$_.Count};$result=&$assert $ev $kinds;$status=if($result-is[string]){$result}elseif($result){'PASS'}else{'FAIL'};$profiles.Add([ordered]@{profile=$letter;mode=$mode;logicalOperations=$logical;ports=$ports;durationMs=[math]::Round($watch.Elapsed.TotalMilliseconds,2);nativeEvents=$ev.Count;uniqueEvents=@($ev.eventId|Sort-Object -Unique).Count;connectionEntities=@($ev.connectionEntityId|Sort-Object -Unique).Count;processAttributed=@($ev|?{$_.process.processId-gt0}).Count;IPv4=@($ev|?{$_.local.addressFamily-eq'IPv4'}).Count;IPv6=@($ev|?{$_.local.addressFamily-eq'IPv6'}).Count;operations=$kinds;lostEvents=$health.sourceLosses;queueDepth=$health.queueDepth;agentCpuDeltaMs=[math]::Round($agent.TotalProcessorTime.TotalMilliseconds-$cpu0,2);agentWorkingSetBytes=$agent.WorkingSet64;sourceMultiplicity='native ETW operations are not asserted one-to-one with application calls';unexplainedLoss=if($status-eq'FAIL'){$logical}else{0};status=$status})}
