 if($agent-and-not$agent.HasExited){Stop-Process $agent.Id -Force;$agent.WaitForExit()};@('OpenSecurityPlatform-NetworkLifecycle-v1','OpenSecurityPlatform-RegistryLifecycle-v1','OpenSecurityPlatform-ProcessLifecycle-v1','OpenSecurityPlatform-FileLifecycle-v1')|%{& logman stop $_ -ets 2>$null|Out-Null};Get-ChildItem (Join-Path $run 'network-queue') -Filter '*.json' -ErrorAction SilentlyContinue|Remove-Item -Force
