 Profile A 'normal-workstation-ipv4-tcp' 10 {TcpSuccess 10 $false $false} {param($e,$k)@($e|?{$_.kind-eq'ConnectionAttempted'}).Count-gt0-and@($e|?{$_.kind-eq'ConnectionEstablished'}).Count-gt0}
