 $tupleStart=[DateTimeOffset]::UtcNow;$tuplePort=TcpSuccess 2 $false $false;$tupleEvents=@(Events $tupleStart @($tuplePort) 2);$tupleEntities=@($tupleEvents|?{$_.kind-eq'ConnectionAttempted'}|Select-Object -Expand connectionEntityId -Unique);Add 'tuple-reuse-protection' $(if($tupleEntities.Count-ge2){'PASS'}else{'FAIL'}) @{entities=$tupleEntities.Count;port=$tuplePort}
 $fairFrom=[DateTimeOffset]::UtcNow.AddMinutes(-5).UtcDateTime.ToString('O');$d=[DateTimeOffset]::UtcNow.AddSeconds(90);do{Start-Sleep 2;$counts=(Sql "select (select count(*) from platform.process_events where endpoint_id='$endpoint' and received_at>='$fairFrom')||'|'||(select count(*) from platform.file_events where endpoint_id='$endpoint' and received_at>='$fairFrom')||'|'||(select count(*) from platform.registry_events where endpoint_id='$endpoint' and received_at>='$fairFrom')").Split('|')}while(@($counts|%{[long]$_}|?{$_-eq0}).Count-gt0-and[DateTimeOffset]::UtcNow-lt$d);Add 'telemetry-partition-fairness' $(if(@($counts|%{[long]$_}|?{$_-eq0}).Count-eq0){'PASS'}else{'FAIL'}) @{process=[long]$counts[0];file=[long]$counts[1];registry=[long]$counts[2]}
